correct.username_cli.py:
"""Public interface for username validation."""
import sys
from username import accept


def main(argv):
    try:
        if len(argv) != 1:
            raise ValueError("exactly one username is required")
        print(accept(argv[0]))
    except ValueError:
        print("invalid username", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

