"""Username CLI tests."""
import subprocess
import sys
import unittest


def invoke(value):
    return subprocess.run([sys.executable, "-B", "username_cli.py", value],
                          capture_output=True, text=True, timeout=5)


class UsernameRegressionTests(unittest.TestCase):
    def test_empty(self):
        result = invoke("")
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, "")
        self.assertEqual(result.stderr, "invalid username\n")

    def test_spaces_and_tabs(self):
        for value in ("   ", "\t", " \t "):
            with self.subTest(value=repr(value)):
                result = invoke(value)
                self.assertEqual(result.returncode, 2)
                self.assertEqual(result.stdout, "")
                self.assertEqual(result.stderr, "invalid username\n")

    def test_visible_names(self):
        for value in ("Ada", "Maya"):
            with self.subTest(value=value):
                result = invoke(value)
                self.assertEqual(result.returncode, 0)
                self.assertEqual(result.stdout, value + "\n")
                self.assertEqual(result.stderr, "")


if __name__ == "__main__":
    unittest.main()

